import re,os
anch=open('specs/sk-doc/066-skill-readability-refinement/005-mcp-tooling/007-mcp-notion/scratch/inbound-anchors.txt').read().splitlines()
for line in anch:
    target, rest = line.split(': ',1)
    if 'no inbound' in rest.lower() or not rest.strip():
        print(target,'-> none'); continue
    # extract citing file:line pairs after 'at '
    at=rest.split(' at ',1)
    pairs=[]
    if len(at)>1:
        for p in re.findall(r'(\S+?):(\d+)(?=[,.]|$)', at[1]):
            pairs.append(p)
    secs=set()
    missing=[]
    for f,ln in pairs:
        try: ls=open(f).read().splitlines()
        except: missing.append((f,ln,'NOFILE')); continue
        if int(ln)>len(ls): missing.append((f,ln,'OOR')); continue
        text=ls[int(ln)-1]
        for s in re.findall(r'§\s*(\d+)', text): secs.add(int(s))
        for s in re.findall(r'section\s+(\d+)', text, re.I): secs.add(int(s))
        if target.split('/')[-1] not in text and target not in text:
            missing.append((f,ln,'NO-TARGET-MENTION'))
    heads=[]
    try:
        for l in open(target).read().splitlines():
            m=re.match(r'^## (\d+)\.', l)
            if m: heads.append(int(m.group(1)))
    except Exception as e: pass
    bad=[s for s in sorted(secs) if s not in heads]
    print(f'{target.split("/")[-1]}: cites={sorted(secs)} heads={heads} bad={bad} pairs={len(pairs)} odd={missing[:3]}')
